patch:
diff --git a/pkg/buildx/commands/lint.go b/pkg/buildx/commands/lint.go
index 6a12b99..5a9d870 100644
--- a/pkg/buildx/commands/lint.go
+++ b/pkg/buildx/commands/lint.go
@@ -27,7 +27,8 @@ import (

 const (
 	Hadolint = "hadolint/hadolint:2.12.0"
-	Semgrep  = "returntocorp/semgrep:1.34.1"
+	// What: audited scanner digest; why: preserve the tested engine/rule grammar. TS: const Semgrep = auditedImage.
+	Semgrep  = "docker.io/semgrep/semgrep@sha256:81474464c1f07483ba0682a44787fd93c91397419762a04abe2bafaae396304b"
 )

 // LintFailed is the error returned when linting fails.  Used to fail the build.
@@ -350,7 +351,8 @@ func RunHadolint(ctx context.Context, client *client.Client, platform ocispecs.P
 }

 func RunSemgrep(ctx context.Context, client *client.Client, platform ocispecs.Platform, dockerfile *build.DockerfileInputs) (CaptureOutput, error) {
-	args := []string{"/usr/local/bin/semgrep", "scan", "--config=p/dockerfile", "--json", "--quiet", "--disable-version-check", dockerfile.Filename}
+	// What: command arguments; why: use the tested executable and explicit Dockerfile target selection. TS: const args = [...].
+	args := []string{"/usr/bin/semgrep", "scan", "--scan-unknown-extensions", "--config=p/dockerfile", "--json", "--quiet", "--disable-version-check", dockerfile.Filename}
 	return RunImage(ctx, Semgrep, args, client, platform, dockerfile)
 }
